105:            let enabled = config.enabled;
106:            let tools_visible_for_thread = !matches!(
107:                input.session_source,
108:                SessionSource::SubAgent(SubAgentSource::Review)
109:            );
110:            let tools_available_for_thread =
111:                input.persistent_thread_state_available && tools_visible_for_thread;
112:            input.thread_store.insert(config);
113:            let accounting_state = input
114:                .thread_store
115:                .get_or_init::<GoalAccountingState>(GoalAccountingState::default);
116:            let Ok(thread_id) = ThreadId::from_string(input.thread_store.level_id()) else {
117:                return;
118:            };
119:            let root_accounting_state = input
120:                .session_source
121:                .parent_thread_id()
122:                .or_else(|| {
123:                    ThreadId::from_string(input.session_store.level_id())
124:                        .ok()
125:                        .filter(|_| input.session_source.is_non_root_agent())
126:                })
127:                .and_then(|parent_thread_id| {
128:                    self.goal_service
129:                        .runtime_for_thread(parent_thread_id)
130:                        .or_else(|| {
131:                            ThreadId::from_string(input.session_store.level_id())
132:                                .ok()
133:                                .and_then(|root_thread_id| {
134:                                    self.goal_service.runtime_for_thread(root_thread_id)
135:                                })
136:                        })
137:                })
138:                .map(|parent| {
139:                    parent
140:                        .root_accounting_state()
141:                        .unwrap_or_else(|| parent.accounting_state())
142:                });
143:            let runtime = input.thread_store.get_or_init::<GoalRuntimeHandle>(|| {
144:                GoalRuntimeHandle::new(
145:                    thread_id,
146:                    Arc::clone(&self.state_dbs),
147:                    self.event_emitter.clone(),
148:                    self.metrics.clone(),
149:                    self.thread_manager.clone(),
150:                    accounting_state,
151:                    GoalRuntimeConfig {
152:                        analytics: self.analytics.clone(),
153:                        enabled,
154:                        tools_available_for_thread,
155:                        tools_visible_for_thread,
156:                        root_accounting_state,
157:                    },
158:                )
159:            });
160:            runtime.set_enabled(enabled);
161:            self.goal_service.register_runtime(&runtime);
