async fn steer(
    session: &Arc<Session>,
    request: WithTurnExtensionData<TurnInputRequest>,
    expected_turn_id: String,
    submission_id: String,
) -> CodexResult<TurnInputSubmission> {
    let WithTurnExtensionData {
        request,
        turn_extension_init,
    } = request;
    let TurnInputRequest {
        mut input,
        thread_settings,
        start,
        additional_context,
        responsesapi_client_metadata,
        ..
    } = request;
    let origin = UserInputOrigin::from_turn_trigger(start.turn_trigger.as_deref());
    if !matches!(&input, SubmittedTurnInput::UserInput { .. }) {
        return Err(CodexErr::InvalidRequest(
            "only user input can steer a turn".to_string(),
        ));
    }
    let settings = PreparedTurnInputSettings::prepare(
        session,
        WithTurnExtensionData {
            request: thread_settings,
            turn_extension_init,
        },
        start,
    )
    .await?;
    match session
        .steer_input(
            &mut input,
            /*sender_messages*/ None,
            additional_context,
            Some(expected_turn_id.as_str()),
            settings.required_active_final_output_json_schema(),
            responsesapi_client_metadata,
            origin,
        )
        .await
    {
        Ok((turn_id, root_turn_id)) => {
            settings.apply_steered(session, submission_id).await?;
            Ok(TurnInputSubmission::Steered {
                turn_id,
                root_turn_id,
            })
        }
        Err(reason) => Ok(TurnInputSubmission::NotSubmitted { reason }),
    }
}

impl Session {
    /// Called under the active-turn lock before running any task or lifecycle callback.
    pub(crate) async fn record_started_turn(
        &self,
        turn_id: &str,
        attribution: Option<codex_history::TurnAttribution>,
    ) {
        let mut state = self.state.lock().await;
        state.last_started_turn_id = Some(turn_id.to_owned());
        if let Some(attribution) = attribution {
            state.turn_attribution = Some(attribution);
        }
    }

    #[expect(
        clippy::await_holding_invalid_type,
        reason = "The admission lock keeps the previous turn stable while capturing its attribution."
    )]
    pub(crate) async fn reserve_pending_work_turn(
        &self,
    ) -> Option<(Arc<tokio::sync::Mutex<TurnState>>, TurnStartOptions)> {
        let mut active_turn = self.active_turn.lock().await;
        if active_turn.is_some() {
            return None;
        }
        let needs_new_turn = self.input_queue.has_trigger_turn_mailbox_items().await;
        if !needs_new_turn && !self.has_outstanding_durable_sleep() {
            return None;
        }
        let active_turn = active_turn.get_or_insert_with(ActiveTurn::default);
        let previous_options = if needs_new_turn {
            Default::default()
        } else {
            self.state
                .lock()
                .await
                .turn_attribution
                .as_ref()
                .map(codex_history::TurnAttribution::start_options)
                .unwrap_or_default()
        };
        Some((Arc::clone(&active_turn.turn_state), previous_options))
    }

    pub(crate) async fn route_realtime_text_input(
        self: &Arc<Self>,
        text: String,
    ) -> Result<(), &'static str> {
        let submission_id = Uuid::now_v7().to_string();
        let submission = handle(
            self,
            TurnInputRequest::user_input(vec![UserInput::Text {
                text,
                text_elements: Vec::new(),
            }])
            .on_start(TurnStartOptions {
                turn_trigger: Some("realtime".to_string()),
                ..Default::default()
            }),
            TurnInputMode::StartOrSteer,
            submission_id.clone(),
        )
        .await;
        match submission {
            Ok(TurnInputSubmission::Started { .. } | TurnInputSubmission::Steered { .. }) => {}
            Ok(TurnInputSubmission::NotSubmitted {
                reason: NotSubmittedReason::ServerDraining,
            }) => {
                return Err("Server is draining; retry the turn after reconnecting");
            }
            Ok(TurnInputSubmission::NotSubmitted { reason }) => {
                self.send_event_raw(Event {
                    id: submission_id,
                    msg: EventMsg::Error(ErrorEvent {
                        misalignment: None,
                        message: format!("failed to submit turn input: {reason:?}"),
                        codex_error_info: Some(CodexErrorInfo::BadRequest),
                    }),
                })
                .await;
            }
            Err(error) => {
                self.send_event_raw(Event {
                    id: submission_id,
                    msg: EventMsg::Error(error.to_error_event(/*message_prefix*/ None)),
                })
                .await;
            }
        }
        Ok(())
    }

    async fn clear_reserved_idle_turn(&self, turn_state: &Arc<tokio::sync::Mutex<TurnState>>) {
        let mut active_turn_guard = self.active_turn.lock().await;
        if let Some(active_turn) = active_turn_guard.as_ref()
            && active_turn.task.is_none()
            && Arc::ptr_eq(&active_turn.turn_state, turn_state)
        {
            *active_turn_guard = None;
        }
    }

    /// Inject additional user input or a standalone tool output into the active turn.
    ///
    /// Returns the active turn id when accepted.
    #[expect(
        clippy::await_holding_invalid_type,
        reason = "active turn checks and turn state updates must remain atomic"
    )]
    #[expect(
        clippy::too_many_arguments,
        reason = "sender evidence is prepared separately before acquiring the admission lock"
    )]
    async fn steer_input(
        &self,
        input: &mut SubmittedTurnInput,
        sender_messages: Option<&GuardianSenderMessages>,
        additional_context: BTreeMap<String, AdditionalContextEntry>,
        expected_turn_id: Option<&str>,
        required_final_output_json_schema: Option<&Value>,
        responsesapi_client_metadata: Option<HashMap<String, String>>,
        origin: UserInputOrigin,
    ) -> Result<(String, String), NotSubmittedReason> {
        let mut active = self.active_turn.lock().await;
        let Some(active_turn) = active.as_mut() else {
            return Err(NotSubmittedReason::NoActiveTurn);
        };

        let Some(active_task) = active_turn.task.as_ref() else {
            return Err(NotSubmittedReason::NoActiveTurn);
        };
        let active_turn_id = &active_task.turn_context.sub_id;

        if let Some(expected_turn_id) = expected_turn_id
            && expected_turn_id != active_turn_id
        {
            return Err(NotSubmittedReason::ExpectedTurnMismatch {
                expected: expected_turn_id.to_string(),
                actual: active_turn_id.clone(),
            });
        }

        match active_task.kind {
            crate::state::TaskKind::Regular => {}
            crate::state::TaskKind::Review => {
                return Err(NotSubmittedReason::ActiveTurnNotSteerable {
                    turn_kind: NonSteerableTurnKind::Review,
                });
            }
            crate::state::TaskKind::Compact => {
                return Err(NotSubmittedReason::ActiveTurnNotSteerable {
                    turn_kind: NonSteerableTurnKind::Compact,
                });
            }
        }

        if matches!(input, SubmittedTurnInput::UserInput { content, .. } if content.is_empty()) {
            return Err(NotSubmittedReason::EmptyInput);
        }
        // Compare JSON values directly instead of serialized schema text.
        // Value equality ignores object key order while preserving array and
        // scalar distinctions; broader JSON Schema equivalence is out of scope.
        if let Some(required_schema) = required_final_output_json_schema
            && active_task.turn_context.final_output_json_schema.as_ref() != Some(required_schema)
        {
            return Err(NotSubmittedReason::ActiveTurnOutputSchemaMismatch);
        }
        let mut pending_input = merge_additional_context_input(self, additional_context).await;

        if let Some(responsesapi_client_metadata) = responsesapi_client_metadata {
            active_task
                .turn_context
                .turn_metadata_state
                .set_responsesapi_client_metadata(responsesapi_client_metadata);
        }

        let input = match input {
            SubmittedTurnInput::UserInput { content, client_id } => {
                active_task
                    .turn_context
                    .session_telemetry
                    .user_prompt(content);
                TurnInput::UserInput {
                    content: std::mem::take(content),
                    client_id: client_id.clone(),
                    metadata: super::UserInputMetadata {
                        acceptance_order: Some(self.reserve_user_input_order().await),
                        origin,
                    },
                }
            }
            input => {
                pending_turn_input(self, input.clone(), sender_messages, active_turn_id, origin)
                    .await
            }
        };
        pending_input.push(input);
        self.input_queue
            .extend_pending_input_and_accept_mailbox_delivery_for_turn_state(
                active_turn.turn_state.as_ref(),
                pending_input,
            )
            .await;
        Ok((
            active_turn_id.clone(),
            active_task.turn_context.root_turn_id(),
        ))
    }
}

async fn merge_additional_context_input(
    session: &Session,
    additional_context: BTreeMap<String, AdditionalContextEntry>,
) -> Vec<TurnInput> {
    let additional_context_input = {
        let mut state = session.state.lock().await;
        state.additional_context.merge(additional_context)
    };
    additional_context_input
        .into_iter()
        .map(|item| session.annotate_client_response_item(item))
        .map(TurnInput::ResponseItem)
        .collect()
}

async fn capture_sender_user_messages(
    session: &Session,
    input: &mut SubmittedTurnInput,
) -> Option<GuardianSenderMessages> {
    let SubmittedTurnInput::ResponseItem(
        item @ ResponseItem::FunctionCallOutput { call_id: None, .. },
    ) = input
    else {
        return None;
    };
    Session::assign_missing_response_item_id(item);
    session
        .services
        .local_agent_runtime
        .capture_sender_user_messages(item, session.thread_id)
        .await
}

async fn pending_turn_input(
    session: &Session,
    input: SubmittedTurnInput,
    sender_messages: Option<&GuardianSenderMessages>,
    turn_id: &str,
    origin: UserInputOrigin,
) -> TurnInput {
    match input {
        SubmittedTurnInput::UserInput { content, client_id } => TurnInput::UserInput {
            content,
            client_id,
            metadata: super::UserInputMetadata {
                acceptance_order: Some(session.reserve_user_input_order().await),
                origin,
            },
        },
        SubmittedTurnInput::ResponseItem(item)
            if matches!(
                &item,
                ResponseItem::FunctionCallOutput { call_id: None, .. }
            ) =>
        {
            let metadata = if let Some(fragment) = sender_messages {
                let mut messages = SenderUserMessages {
                    receiver_turn_id: turn_id.to_owned(),
                    receiver_message_id: fragment.delivery.clone(),
                    text: fragment.render(),
                };
                messages.bound();
                Some(CodexHarnessMetadata {
                    user_input_order: Some(session.reserve_user_input_order().await),
                    sender_user_messages: Some(Box::new(messages)),
                    ..Default::default()
                })
            } else {
                None
            };
            TurnInput::FunctionCallOutput(ResponseItemEnvelope { item, metadata })
        }
        SubmittedTurnInput::ResponseItem(item) => TurnInput::ResponseItem(item.into()),
        SubmittedTurnInput::InterAgentCommunication(communication) => {
            TurnInput::InterAgentCommunication(communication)
        }
    }
}

