  // ---- controlled-task goal projection (provider payload) -----------------
  // The durable record's CURRENT goal — original requirement plus every valid
  // amendment — must reach the model in the request it actually answers:
  // ordinary turns, amend turns, custom-message wakes (deliverCustomMessage
  // never runs before_agent_start), post-compaction and resumed sessions. The
  // system-prompt status block cannot cover those windows, so the projection
  // rides the extensible provider payload and is re-derived from the durable
  // record on EVERY request (never the session's possibly-compacted memory).
  // Full text, not a prefix: a truncated goal would silently narrow the
  // authorization. An unreadable original is an explicit omission with the
  // recovery action — never passed off as the complete goal.
  const GOAL_MARKER = '[orbit-goal]';
  const goalProjectionRecorded = new Set(); // `${taskDir}:${projectionSha256}`
  async function goalProjectionText(bound) {
    const taskDir = bound.taskDir;
    const state = bound.state ?? {};
    const hash = buffer => createHash('sha256').update(buffer).digest('hex');
    let instruction;
    try {
      instruction = await fs.readFile(path.join(taskDir, 'instruction.txt'));
    } catch (error) {
      return { text: `${GOAL_MARKER} 目标投影不完整：无法读取任务原要求 ${path.join(taskDir, 'instruction.txt')}` +
        `（${String(error?.message || error)}）。会话中的先前内容或片段不能当作完整授权；` +
        '先核对任务记录、恢复原件可读，或向用户确认目标后再继续。' };
    }
    const amendmentLines = [];
    const amendments = Array.isArray(state.amendments) ? state.amendments : [];
    let omitted = 0;
    for (const [index, amendment] of amendments.entries()) {
      const rel = typeof amendment?.path === 'string' ? amendment.path : null;
      try {
        if (!rel) throw new Error('missing amendment path');
        const content = await fs.readFile(path.join(taskDir, rel));
        amendmentLines.push(`${index + 1}.（来源 ${amendment?.source?.kind ?? 'unknown'}/${amendment?.source?.id ?? 'unknown'}，` +
          `sha256:${hash(content)}，完整原文）${content.toString('utf8')}`);
      } catch (error) {
        omitted += 1;
        amendmentLines.push(`${index + 1}.（无法读取 ${rel ?? 'unknown'}：${String(error?.message || error)}；该修订未送达，不视为已生效）`);
      }
    }
    const lines = [
      `${GOAL_MARKER} 当前受控任务目标（程序来源，取自任务记录 ${taskDir}；以下为完整原文与全部有效修订，不是摘要或前缀）：`,
      `原要求（来源 native message ${state.instruction_source?.id ?? 'unknown'}，sha256:${hash(instruction)}，` +
        `${instruction.length} 字节，完整原文）：`,
      instruction.toString('utf8'),
    ];
    if (amendmentLines.length) lines.push(`有效修订 ${amendmentLines.length} 条（逐条完整原文；检查与通知以最新版本为准）：`, ...amendmentLines);
    else lines.push('当前无有效修订。');
    if (omitted) lines.push(`注意：${omitted} 条修订无法读取，未送达部分不构成已生效授权。`);
    lines.push('授权边界：用户明确暂停、先讨论或取消优先于本目标；独立问题只回答。交付完成必须经当前版本的独立终检与真实停止门；' +
      '口头继续、状态重述、工具/消息/TODO 数量都不是有价值进展或交付；真实在途等待须指向此刻确认存活的具体句柄。');
    return { text: lines.join('\n') };
  }
  // Append the projection to one request; record the first delivery of each
  // projection version (source, bytes, hash and real model — never the raw
  // payload) so live runs can trace what goal text actually left this process.
  async function injectGoalProjection(payload, bound, sessionId, ctx) {
    if (!payload) return null;
    const projection = await goalProjectionText(bound);
    if (!projection) return null;
    const injected = appendInstructionToPayload(payload, projection.text);
    if (!injected) return null;
    const sha = createHash('sha256').update(projection.text).digest('hex');
    const key = `${bound.taskDir}:${sha}`;
    if (!goalProjectionRecorded.has(key)) {
      goalProjectionRecorded.add(key);
      recordCollabFor(bound.taskDir, {
        kind: 'goal_projection', at: Date.now(),
        session_id: sessionId, agent_id: sdk.MAIN_AGENT_ID,
        task_id: bound.state?.id ?? null,
        model: ctx?.model ? `${ctx.model.provider}/${ctx.model.id}` : null,
        channel: 'provider_payload',
        instruction_source: bound.state?.instruction_source?.id ?? null,
        amendments: Array.isArray(bound.state?.amendments) ? bound.state.amendments.length : null,
        projection_bytes: Buffer.byteLength(projection.text), projection_sha256: `sha256:${sha}`,
        delivered_claim: 'the extension appended the durable-record goal to this request payload; no server receipt and no model-compliance claim',
      });
    }
    return injected;
  }

