  // 1e. C02 goal projection: the CURRENT durable goal (original requirement +
  //     valid amendments) rides the extensible provider payload of ordinary,
  //     amend, custom-wake and resumed requests — the system-prompt status
  //     block never reaches custom-message wakes. Full text with traceable
  //     source/sha; an unreadable original is an explicit omission with a
  //     recovery action, never a prefix passed off as complete authorization.
  {
    const goalCount = text => (String(text).match(/\[orbit-goal\]/g) ?? []).length;
    const goalTextOf = out => (out?.payload ?? out)?.messages?.at(-1)?.content ?? JSON.stringify(out ?? {});
    const goalFacts = count => waitFor(entries => entries.filter(e => e.kind === 'goal_projection').length >= count)
      .then(entries => entries.filter(e => e.kind === 'goal_projection'));

    // (a) ordinary request: full original requirement + standing boundary,
    //     once; the first-append fact pins the real input digest and hash.
    const ordinary = await emit('before_provider_request',
      { payload: { messages: [{ role: 'user', content: 'ordinary follow-up' }] } }, ctx);
    const ordinaryText = goalTextOf(ordinary);
    assert.equal(goalCount(ordinaryText), 1, 'the current goal rides the ordinary request payload');
    assert.ok(ordinaryText.includes('Original requirement.'), 'the projection carries the full original requirement');
    assert.ok(ordinaryText.includes('以下为完整原文') && ordinaryText.includes('授权边界'),
      'completeness is claimed only together with the standing authorization boundary');
    const factsA = await goalFacts(1);
