  // Later requests re-derive the projection from the durable record and are
  // not individually recorded.
  async function injectGoalProjection(payload, bound, sessionId, ctx) {
    if (!payload) return null;
    const projection = await goalProjectionText(bound);
    if (!projection) return null;
    const injected = appendInstructionToPayload(payload, projection.text);
    if (!injected) return null;
    const sha = createHash('sha256').update(projection.text).digest('hex');
    const model = ctx?.model ? `${ctx.model.provider}/${ctx.model.id}` : null;
    const key = `${bound.taskDir}:${sha}:${model}`;
    if (!goalProjectionRecorded.has(key)) {
      goalProjectionRecorded.add(key);
      const binding = readRootBinding(bound.taskDir, { fingerprint: false });
      recordCollabFor(bound.taskDir, {
        kind: 'goal_projection', at: Date.now(),
        session_id: sessionId, agent_id: sdk.MAIN_AGENT_ID,
        task_id: bound.state?.id ?? null,
