      if (!projection) return;
      recordGoalProjection(bound, sessionId, ctx, projection.text, 'context_hook');
      return { messages: [...event.messages, { role: 'user', content: projection.text, timestamp: Date.now() }] };
    } catch { /* projection is best-effort; never block the request */ }
  });


