      const command = `/usr/bin/sandbox-exec -p ${quote(sandboxProfile(root, allowed))} /usr/bin/env -i PATH=${quote(process.env.PATH || '/usr/bin:/bin')} /bin/bash --noprofile --norc -c ${quote(input.command)}`;
